"""
Is there a FAST library FP4/FP8 GEMM (cuBLAS via torch._scaled_mm) on this B200?
Triton's tl.dot_scaled is ~6x SLOWER than tf32. Test torch._scaled_mm with
float8 and (if available) float4 to see if the cuBLAS path delivers FP4/FP8's
real tensor-core throughput. If _scaled_mm FP4 >> tf32, the brief's premise can
be salvaged with a library backend; if not, FP4 is genuinely slow here.
"""
import torch
dev = "cuda"
torch.manual_seed(0)
torch.backends.cuda.matmul.allow_tf32 = True

print("torch", torch.__version__)
print("has _scaled_mm:", hasattr(torch, "_scaled_mm"))
for nm in ["float8_e4m3fn","float8_e5m2","float4_e2m1fn_x2","float4_e2m1fn","uint8"]:
    print(f"  dtype {nm}:", hasattr(torch, nm))

def bench(fn, niter=30, warmup=10):
    for _ in range(warmup):
        try: fn()
        except Exception as e: return None, str(e)
    torch.cuda.synchronize()
    e0=torch.cuda.Event(enable_timing=True); e1=torch.cuda.Event(enable_timing=True)
    e0.record()
    for _ in range(niter): fn()
    e1.record(); torch.cuda.synchronize()
    return e0.elapsed_time(e1)/niter*1e3, None

def run(n):
    print(f"\n== square n={n} ==")
    A=torch.randn(n,n,device=dev,dtype=torch.float32)
    B=torch.randn(n,n,device=dev,dtype=torch.float32)
    t_tf32,_=bench(lambda: torch.mm(A,B))
    print(f"  tf32 mm            : {t_tf32:8.1f} us")
    # bf16 baseline
    Ab=A.bfloat16(); Bb=B.bfloat16()
    t_bf16,_=bench(lambda: torch.mm(Ab,Bb))
    print(f"  bf16 mm            : {t_bf16:8.1f} us  [{t_bf16/t_tf32:.2f}x]")
    # fp8 e4m3 via _scaled_mm
    try:
        Af=A.to(torch.float8_e4m3fn); Bf=B.t().contiguous().to(torch.float8_e4m3fn).t()
        scaleA=torch.tensor(1.0,device=dev); scaleB=torch.tensor(1.0,device=dev)
        def f8():
            return torch._scaled_mm(Af, Bf, scale_a=scaleA, scale_b=scaleB, out_dtype=torch.float32)
        t,err=bench(f8)
        if t: print(f"  fp8 e4m3 _scaled_mm: {t:8.1f} us  [{t/t_tf32:.2f}x]")
        else: print(f"  fp8 e4m3 _scaled_mm: FAIL {err[:120]}")
    except Exception as e:
        print(f"  fp8 e4m3 setup FAIL: {str(e)[:160]}")
    # fp4 e2m1 via _scaled_mm (rowwise/block scales) -- try the new API forms
    if hasattr(torch, "float4_e2m1fn_x2"):
        try:
            n2=n//2
            Ap=torch.randint(0,255,(n,n2),device=dev,dtype=torch.uint8).view(torch.float4_e2m1fn_x2)
            Bp=torch.randint(0,255,(n,n2),device=dev,dtype=torch.uint8).view(torch.float4_e2m1fn_x2).t()
            # block scales (e8m0/e4m3) -- try mxfp4 with 32-block scales
            sa=torch.ones((n, n//32),device=dev,dtype=torch.float8_e8m0fnu) if hasattr(torch,"float8_e8m0fnu") else torch.ones((n,n//32),device=dev,dtype=torch.float8_e4m3fn)
            sb=torch.ones((n, n//32),device=dev,dtype=sa.dtype)
            def f4():
                return torch._scaled_mm(Ap, Bp, scale_a=sa, scale_b=sb, out_dtype=torch.bfloat16)
            t,err=bench(f4)
            if t: print(f"  fp4 e2m1 _scaled_mm: {t:8.1f} us  [{t/t_tf32:.2f}x]  <<< NATIVE FP4")
            else: print(f"  fp4 e2m1 _scaled_mm: FAIL {err[:200]}")
        except Exception as e:
            print(f"  fp4 e2m1 setup FAIL: {str(e)[:200]}")

for n in [2048, 4096]:
    run(n)

